<script lang="ts">
 import {tick,onMount} from 'svelte';
 import GameCard from '$lib/components/GameCard.svelte';
 import PowerMarker from '$lib/components/PowerMarker.svelte';
 import ChoiceSlip from '$lib/components/ChoiceSlip.svelte';
 import ScoreSheet from '$lib/components/ScoreSheet.svelte';
 import {allCards,suits,type GameCard as Card} from '$lib/data/game';
 let kind=$state('all'), suit=$state('all'),query=$state(''),backs=$state(false);
 let selected=$state<Card|null>(null),dialog:HTMLDialogElement;
 onMount(()=>{kind=new URLSearchParams(location.search).get('kind')??'all';});
 const categories=[['all','All cards','88'],['imp','Imps','10'],['arcana','Major Arcana','22'],['minor','Minor Arcana','56'],['accessories','Table essentials','']];
 let visible=$derived(allCards.filter(c=>(kind==='all'||c.kind===kind)&&(suit==='all'||('suit' in c&&c.suit===suit))&&`${c.name} ${'rule' in c?c.rule:''} ${'power' in c?c.power:''}`.toLowerCase().includes(query.toLowerCase())));
 async function inspect(card:Card){selected=card;await tick();dialog.showModal();}
</script>
<svelte:head><title>The components — Hell’s Bells</title><meta name="description" content="Explore all 56 playing cards, 22 Major Arcana, ten imp characters, and table essentials for Hell’s Bells."/></svelte:head>
<main id="main" class="gallery-main"><section class="gallery-intro"><div><p class="eyebrow">HELL’S BELLS</p><h1>Component gallery</h1><p>56 playing cards, 22 Major Arcana, and 10 imp characters.<br/>Select a component to inspect its artwork and rules.</p></div><div class="gallery-fan"><div><GameCard card={allCards[0]}/></div><div><GameCard card={allCards[9]}/></div></div></section>
<section class="collection" aria-label="Component collection"><nav class="gallery-tabs" aria-label="Component types">{#each categories as [value,label,count]}<button aria-pressed={kind===value} onclick={()=>kind=value}>{label}<span>{count}</span></button>{/each}</nav>
{#if kind!=='accessories'}<div class="gallery-toolbar"><label>Search components<input type="search" bind:value={query} placeholder="Name, power, or rule…"/></label><label>Suit<select bind:value={suit}><option value="all">All suits</option>{#each suits as s}<option>{s}</option>{/each}</select></label><label class="checkbox"><input type="checkbox" bind:checked={backs}/> Show card backs</label></div><p class="collection-count" aria-live="polite">{visible.length} cards · Select a card for a closer look</p><div class="gallery-grid">{#each visible as card (card.id)}<div class="gallery-item"><div class="card-wrap"><GameCard {card} back={backs}/><button onclick={()=>inspect(card)} aria-label={`Inspect ${card.name}`}></button></div><p><span>{card.kind==='imp'?'IMP':card.kind==='arcana'?'MAJOR ARCANA':'MINOR ARCANA'}</span><b>{card.name}</b></p></div>{:else}<div class="empty"><h2>No cards in this corner.</h2><p>Try a different suit or search.</p><button onclick={()=>{query='';suit='all';kind='all';}}>Reset filters</button></div>{/each}</div>{:else}<div class="accessories"><section><ScoreSheet sample/><h2>The score sheet</h2><p>One ledger per player. Record bids, counted tricks, original round penalties, recoveries, and cumulative totals. Use paper or print a blank copy.</p><button class="button" onclick={()=>window.print()}>Print a blank ledger ↗</button></section><section><div class="marker-demo"><PowerMarker/><PowerMarker spent/><ChoiceSlip/></div><h2>Markers & secret choices</h2><p>Use a coin or token to mark a spent imp power. Paper slips let players conceal bids and player selections. No special tokens are required.</p><h3>Also on the table</h3><p>A shared face-down undealt reserve, a separate concealed discard pile, and public piles of won tricks.</p></section></div><div class="print-ledger"><ScoreSheet/></div>{/if}
</section></main>
<dialog bind:this={dialog} onclose={()=>selected=null}><button class="dialog-close" onclick={()=>dialog.close()}>Close <span>×</span></button>{#if selected}<div class="inspector"><GameCard card={selected} back={backs}/></div><div class="inspector-text"><h2>{selected.name}</h2>{#if 'rule' in selected}<p>{selected.rule}</p>{:else}<p>Rank {selected.rank} of 14 · {selected.suit}. Ace is low; King is high.</p>{/if}</div>{/if}</dialog>
